import sys, json, importlib.metadata as m
items=[]
for name in ('aghr','aghr-studio'):
 try:
  d=m.distribution(name)
  items.append({'name':name,'status':'INSTALLED','version':d.version,'location':str(d.locate_file('')),'entry_points':[str(e) for e in d.entry_points]})
 except m.PackageNotFoundError:
  items.append({'name':name,'status':'NOT_INSTALLED'})
print(json.dumps({'python':sys.version,'executable':sys.executable,'packages':items}))
